export default function PhilippinesMap({ data, viewMode, onHoverItem }: PhilippinesMapProps) {
  const [hoveredId, setHoveredId] = useState<string | null>(null);

  // Compute maximum count in dataset for opacity scaling
  const maxCount = Math.max(...Object.values(data).map(v => v || 0), 1);

  // Group paths by region for region view highlighting
  const getRegionCount = (regionName: string) => {
    return data[regionName] || 0;
  };

  const getProvinceCount = (provName: string) => {
    return data[provName] || 0;
  };

  return (
    <svg 
      viewBox="0 0 6472 10850" 
      className="w-full h-full max-h-[600px] select-none transition-all duration-300"
      style={{ filter: 'drop-shadow(0px 8px 24px rgba(0, 0, 0, 0.15))' }}
    >
      <g>
        {PROVINCE_PATHS.map((prov) => {
          const regionName = prov.region || provinceToRegionMap[prov.name] || 'Unknown Region';
          const isHovered = hoveredId === prov.id || (hoveredId && viewMode === 'regions' && (PROVINCE_PATHS.find(p => p.id === hoveredId)?.region === regionName));
          
          let count = 0;
          if (viewMode === 'regions') {
            count = getRegionCount(regionName);
          } else {
            count = getProvinceCount(prov.name);
          }

          let baseFill = 'var(--accent-border)';
          let opacity = 0.25;

          if (count > 0) {
            const ratio = count / maxCount;
            // Interpolate Hue: 60 (yellow) down to 0 (red)
            const hue = Math.round(60 - ratio * 60);
            baseFill = `hsl(${hue}, 90%, 50%)`;
            opacity = 0.6 + 0.4 * ratio;
          }

          return (
            <path
              key={prov.id}
              d={prov.path}
              fill={baseFill}
              fillOpacity={opacity}
              stroke="var(--background)"
              strokeWidth={isHovered ? 12 : 3}
              strokeOpacity={0.8}
              className="transition-all duration-150 cursor-pointer"
              style={{
                filter: isHovered 
                  ? `brightness(1.15) drop-shadow(0px 0px 8px ${count > 0 ? baseFill : 'var(--primary-green)'})` 
                  : 'none'
              }}
              onMouseEnter={() => {
                setHoveredId(prov.id);
                if (onHoverItem) {
                  onHoverItem({
                    name: viewMode === 'regions' ? regionName : prov.name,
                    region: regionName,
                    count: count
                  });
                }
              }}
              onMouseLeave={() => {
                setHoveredId(null);
                if (onHoverItem) onHoverItem(null);
              }}
            />
          );
        })}
      </g>
    </svg>
  );
}
